CREATE TABLE public.trades (
    id bigint NOT NULL,
    external_id text NOT NULL,
    isin text NOT NULL,
    contract_date date NOT NULL,
    venue text NOT NULL,
    event_time timestamp with time zone NOT NULL,
    published_at timestamp with time zone,
    price numeric(12,4) NOT NULL,
    quantity numeric(18,4) NOT NULL,
    notional numeric(20,4),
    price_currency text DEFAULT 'EUR'::text NOT NULL,
    ingest_run_id bigint
);


--
-- Name: days; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.days AS
 SELECT ((event_time AT TIME ZONE 'Europe/Berlin'::text))::date AS berlin_date,
    min(event_time) AS first_event,
    max(event_time) AS last_event,
    (count(*))::integer AS n_trades,
    min(price) AS low,
    max(price) AS high
   FROM public.trades
  GROUP BY (((event_time AT TIME ZONE 'Europe/Berlin'::text))::date);


