CREATE TABLE public.ingest_runs (
    id bigint NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    status text NOT NULL,
    source text NOT NULL,
    source_files text[] DEFAULT '{}'::text[] NOT NULL,
    records_seen integer DEFAULT 0 NOT NULL,
    records_kept integer DEFAULT 0 NOT NULL,
    records_upserted integer DEFAULT 0 NOT NULL,
    error text,
    CONSTRAINT ingest_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'ok'::text, 'error'::text])))
);


